// lib/courses.ts

export type InstrutorInfo = {
  nome: string
  descricao: string
}

export type Course = {
  id: number
  titulo: string
  subtitulo: string | null
  categoria: string
  bg: string
  shadow: string
  textColor: string
  emoji: string
  preco: string
  productId: string
  imagem?: string
  slug: string
  descricaoCurta: string
  descricaoLonga: string

  // ── novos campos ──────────────────────────────────────
  publicoAlvo?: string
  cargaHorariaDetalhe?: string
  oQueVaiAprender?: string[]
  instrutor?: InstrutorInfo
  informacoesCurso?: string[]
}

type CourseInput = Omit<Course, 'slug' | 'descricaoCurta' | 'descricaoLonga'> & {
  descricaoCurta?: string
  descricaoLonga?: string
}

// ─────────────────────────────────────────────────────────────────────────
// Slug automático a partir do título (+ subtítulo se houver, + id se colidir)
// ─────────────────────────────────────────────────────────────────────────
function slugify(texto: string): string {
  return texto
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

function gerarDescricaoPadrao(c: CourseInput): string {
  return `O curso ${c.titulo}${c.subtitulo ? ` (${c.subtitulo})` : ''} faz parte da categoria ${c.categoria} e foi desenvolvido para atender às exigências do CONTRAN/DETRAN, com conteúdo teórico completo, material de apoio e certificado válido em todo o território nacional.`
}

