// ─────────────────────────────────────────────────────────────────────────
// Gera slugs únicos e preenche descrições padrão quando não informadas
// ─────────────────────────────────────────────────────────────────────────
const slugsUsados = new Set<string>()

export const courses: Course[] = coursesInput.map((c) => {
  const slugBase = slugify(c.subtitulo ? `${c.titulo}-${c.subtitulo}` : c.titulo)
  let slug = slugBase
  if (slugsUsados.has(slug)) slug = `${slugBase}-${c.id}`
  slugsUsados.add(slug)

  return {
    ...c,
    slug,
    descricaoCurta: c.descricaoCurta ?? `Curso de ${c.categoria.toLowerCase()} — ${c.titulo}${c.subtitulo ? ` (${c.subtitulo})` : ''}.`,
    descricaoLonga: c.descricaoLonga ?? gerarDescricaoPadrao(c),
  }
})

export function getCourseBySlug(slug: string): Course | undefined {
  return courses.find((c) => c.slug === slug)
}

// ─────────────────────────────────────────────────────────────────────────
// Preço, requisitos, estados e validações (igual ao que você já tinha)
// ─────────────────────────────────────────────────────────────────────────
export function parsePreco(preco: string): number {
  return parseFloat(preco.replace('R$', '').replace(/\./g, '').replace(',', '.').trim())
}

export const REQUISITOS_CURSOS: Record<string, string[]> = {
  'Carga Indivisível Formação': ['C', 'D', 'E'],
  'Carga Indivisível Atualização': ['C', 'D', 'E'],
  'Coletivo de Passageiros Formação': ['D', 'E'],
  'Coletivo de Passageiros Atualização': ['D', 'E'],
  'Emergência Formação': ['A', 'B', 'C', 'D', 'E'],
  'Emergência Atualização': ['A', 'B', 'C', 'D', 'E'],
  'Escolar Formação': ['D', 'E'],
  'Escolar Atualização': ['D', 'E'],
  'Produtos Perigosos - MOPP Formação': ['B', 'C', 'D', 'E'],
  'Produtos Perigosos - MOPP Atualização': ['B', 'C', 'D', 'E'],
}

export const ESTADOS_RECICLAGEM: Record<number, string[]> = {
  11: ['AC', 'AL', 'DF', 'MA', 'MT', 'PE', 'RJ', 'SC', 'SE', 'SP', 'TO'],
  12: ['DF', 'ES', 'GO', 'MT', 'MS', 'PE', 'RJ', 'RS', 'SC', 'SP'],
  13: ['AC', 'AL', 'CE', 'DF', 'ES', 'GO', 'MA', 'MT', 'MS', 'PE', 'PR', 'RJ', 'RS', 'SC', 'SE', 'SP', 'TO'],
}

export type User = {
  _id: string
  nome: string
  email: string
  whatsapp: string
  cpf: string
  cnh: string
  categoriaCnh: string[]
  ufCnh: string
  dataNascimento: string
  endereco: {
    logradouro: string
    numero: string
    bairro: string
    cidade: string
    estado: string
    cep: string
  }
  access: boolean
  createdAt: string
  updatedAt: string
  __v: number
}

export type ValidationError = {
  hasError: boolean
  idadeOk: boolean
  categoriaOk: boolean
  requiredCategories: string[]
  userCategories: string[]
}

export type ValidationErrorEstado = {
  hasError: boolean
  estadoOk: boolean
  allowedStates: string[]
  userState: string
}

export function calcularIdade(dataNascimento: string): number {
  const hoje = new Date()
  const nascimento = new Date(dataNascimento)
  let idade = hoje.getFullYear() - nascimento.getFullYear()
  const mes = hoje.getMonth() - nascimento.getMonth()
  if (mes < 0 || (mes === 0 && hoje.getDate() < nascimento.getDate())) idade--
  return idade
}

export function validarRequisitoCurso(course: Course, user: User): ValidationError {
  const idadeOk = calcularIdade(user.dataNascimento) >= 21
  const requiredCategories = REQUISITOS_CURSOS[course.titulo] || []
  const categoriaOk = requiredCategories.length === 0 || requiredCategories.some(cat => user.categoriaCnh.includes(cat))
  return { hasError: !idadeOk || !categoriaOk, idadeOk, categoriaOk, requiredCategories, userCategories: user.categoriaCnh }
}

export function validarEstadoReciclagem(courseId: number, user: User): ValidationErrorEstado {
  const allowedStates = ESTADOS_RECICLAGEM[courseId] || []
  const userState = user.endereco?.estado?.toUpperCase() || ''
  const estadoOk = allowedStates.length === 0 || allowedStates.includes(userState)
  return { hasError: !estadoOk, estadoOk, allowedStates, userState }
}
